import { Children, isValidElement, cloneElement, ReactElement } from "react";

export const enforceAIItemProps = (children: React.ReactNode) => {
  return Children.map(children, (child) => {
    if (isValidElement(child)) {
      const type = child.type as { displayName?: string };
      const props = child.props as Record<string, unknown>;
      const newProps: Record<string, unknown> = {};

      // Enforce defaults only for IconButton
      if (type?.displayName === "IconButton") {
        if (!props.buttonType) {
          newProps.buttonType = "secondary";
        }
      }

      if (Object.keys(newProps).length > 0) {
        return cloneElement(child as ReactElement, newProps);
      }
    }
    return child;
  });
};
